#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<unsigned long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int split_point = n / 2;

    vector<unsigned long> left_part, right_part;

    function<void(int, unsigned long)> create_sums = [&](int i, unsigned long total) {
        if (i == split_point) {
            left_part.push_back(total);
        } else {
            create_sums(i + 1, (total + a[i]) % m);
            create_sums(i + 1, total);
        }
    };

    function<void(int, unsigned long)> create_sums_rest = [&](int i, unsigned long total) {
        if (i == n) {
            right_part.push_back(total);
        } else {
            create_sums_rest(i + 1, (total + a[i]) % m);
            create_sums_rest(i + 1, total);
        }
    };

    create_sums(0, 0);
    create_sums_rest(split_point, 0);

    // Remove duplicates and sort
    vector<unsigned long> unique_left_part = left_part;
    std::sort(unique_left_part.begin(), unique_left_part.end());
    auto last = std::unique(unique_left_part.begin(), unique_left_part.end());
    unique_left_part.erase(last, unique_left_part.end());

    unsigned long best_total_sum = 0;

    for (auto val : right_part) {
        auto it = std::lower_bound(unique_left_part.begin(), unique_left_part.end(), m - val);
        if (it != unique_left_part.begin()) {
            --it;
            unsigned long candidate = *it + val;
            if (candidate > best_total_sum) {
                best_total_sum = candidate;
            }
        }
    }

    cout << best_total_sum << "\n";

    return 0;
}
